	// Тест 2: Флаг включен (Black Friday скидка 30%)
	mockClient.SetFlag("black_friday_discount", true)
	d2 := service.CalculateDiscount(ctx, 1000)
	fmt.Printf("Тест 2 (Флаг=true):  Скидка = %.2f (Ожидалось 300.00)\n", d2)
}

